INSERT INTO dept_closure (ancestor_id, descendant_id, depth) SELECT chain.ancestor_id, nodes.dept_id, chain.depth + 1 FROM dept_closure chain INNER JOIN (
SELECT #{node.deptId} AS dept_id, #{node.parentId} AS parent_id
) nodes ON chain.descendant_id = nodes.parent_id WHERE nodes.parent_id > 0 UNION ALL SELECT nodes.dept_id, nodes.dept_id, 0 FROM (
SELECT #{node.deptId} AS dept_id, #{node.parentId} AS parent_id
) nodes
